-- ============================================================
-- BASE DE DATOS: hse_analysis
-- Proyecto: Análisis de Incidentes HSE con SQL
-- Autor: Sergio Ulises Corona Sánchez
-- Periodo de datos: 2022 - 2024
-- Registros: 2,000 incidentes | 150 empleados | 8 áreas
-- ============================================================

DROP DATABASE IF EXISTS hse_analysis;
CREATE DATABASE hse_analysis
  DEFAULT CHARACTER SET utf8mb4
  DEFAULT COLLATE utf8mb4_spanish_ci;
USE hse_analysis;

-- ------------------------------------------------------------
-- TABLA: areas
-- ------------------------------------------------------------
CREATE TABLE areas (
  area_id      INT PRIMARY KEY AUTO_INCREMENT,
  nombre       VARCHAR(50)  NOT NULL,
  departamento VARCHAR(50)  NOT NULL,
  responsable  VARCHAR(100) NOT NULL
);

