-- ------------------------------------------------------------
-- TABLA: tipos_incidente
-- ------------------------------------------------------------
CREATE TABLE tipos_incidente (
  tipo_id                INT PRIMARY KEY AUTO_INCREMENT,
  categoria              VARCHAR(50)  NOT NULL,
  descripcion            VARCHAR(200) NOT NULL,
  requiere_investigacion TINYINT(1)   NOT NULL DEFAULT 0
);

