-- ------------------------------------------------------------
-- TABLA: incidentes
-- ------------------------------------------------------------
CREATE TABLE incidentes (
  incidente_id           INT PRIMARY KEY AUTO_INCREMENT,
  fecha                  DATE         NOT NULL,
  area_id                INT          NOT NULL,
  tipo_id                INT          NOT NULL,
  empleado_id            INT          NOT NULL,
  severidad              ENUM('Leve','Moderado','Grave','Crítico') NOT NULL,
  costo_directo          DECIMAL(12,2) NOT NULL,
  costo_investigacion    DECIMAL(12,2) NOT NULL,
  dias_perdidos          INT           NOT NULL DEFAULT 0,
  epp_usado              TINYINT(1)    NOT NULL DEFAULT 1,
  reincidencia           TINYINT(1)    NOT NULL DEFAULT 0,
  nivel_riesgo           ENUM('Bajo','Medio','Alto','Crítico') NOT NULL,
  dias_sin_accidente     INT           NOT NULL DEFAULT 0,
  investigacion_completada TINYINT(1)  NOT NULL DEFAULT 1,
  medida_correctiva      VARCHAR(100)  NOT NULL,
  FOREIGN KEY (area_id)     REFERENCES areas(area_id),
  FOREIGN KEY (tipo_id)     REFERENCES tipos_incidente(tipo_id),
  FOREIGN KEY (empleado_id) REFERENCES empleados(empleado_id)
);

